export const createTerminalSession = async (terminalSessionInput: TerminalSessionInput, options?: RequestInit): Promise<TerminalSession> => {

  return customFetch<TerminalSession>(getCreateTerminalSessionUrl(),
  {
    ...options,
    method: 'POST',
    headers: { 'Content-Type': 'application/json', ...options?.headers },
    body: JSON.stringify(
      terminalSessionInput,)
  }
);}




