export const getCloseTerminalSessionUrl = (id: number,) => {




  return `/api/terminal/sessions/${id}`
}

/**
 * @summary Close a terminal session
 */
export const closeTerminalSession = async (id: number, options?: RequestInit): Promise<void> => {

  return customFetch<void>(getCloseTerminalSessionUrl(id),
  {
    ...options,
    method: 'DELETE'


  }
);}




